-- Remove the deterministic development fixtures that were previously created
-- by migration 20260611180000. Keep the explicit IDs so this cleanup cannot
-- affect real users, recurring series, or games.

delete from public.game_events
where id in (
  '92000000-0000-4000-8000-000000000001'::uuid,
  '92000000-0000-4000-8000-000000000002'::uuid,
  '92000000-0000-4000-8000-000000000003'::uuid
)
or recurring_series_id in (
  '91000000-0000-4000-8000-000000000001'::uuid,
  '91000000-0000-4000-8000-000000000002'::uuid
);

delete from public.recurring_game_series
where id in (
  '91000000-0000-4000-8000-000000000001'::uuid,
  '91000000-0000-4000-8000-000000000002'::uuid
);

